() => {
  const scrollContainerRef = useRef<HTMLElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const [isOpen, setIsOpen] = useState(false)
  const [selectedItem, setSelectedItem] = useState<Datum>()
  const handleOpen = () => {
    setIsOpen(true)
    inputRef.current && inputRef.current.focus()
  }
  const selectChange = (item: Datum[] | Datum) => {
    setIsOpen(false)
    if (Array.isArray(item) && item.length) setSelectedItem(item[0])
    triggerRef.current?.focus()
  }
  return (
    <form className={classes.FormPadding}>
      <span id="selected-item-status">
        Selected item: {selectedItem ? selectedItem.text : 'none'}
      </span>

      <AnchoredOverlay
        open={isOpen}
        onOpen={handleOpen}
        onClose={() => setIsOpen(false)}
        width="large"
        focusTrapSettings={{
          initialFocusRef: inputRef,
        }}
        side="inside-top"
        anchorRef={triggerRef}
        renderAnchor={(props) => (
          <Button {...props} aria-describedby="selected-item-status">
            open overlay
          </Button>
        )}
        preventOverflow={false}
      >
        <Autocomplete>
          <div className={classes.OverlayFlexCol}>
            <div className={classes.OverlayInputBar}>
              <Autocomplete.Input
                ref={inputRef}
                className={classes.OverlayInput}
                block
                aria-label="Search"
              />
            </div>
            <div
              ref={scrollContainerRef as RefObject<HTMLDivElement>}
              className={classes.OverlayScroll}
            >
              <Autocomplete.Menu
                items={items}
                selectedItemIds={[]}
                customScrollContainerRef={scrollContainerRef}
                aria-labelledby="autocompleteLabel"
                onSelectedChange={selectChange}
              />
            </div>
          </div>
        </Autocomplete>
      </AnchoredOverlay>
    </form>
  )
}

