() => {
  const titleId = React.useId()
  const [pageIndex, setPageIndex] = React.useState(0)
  const pageSize = 10
  const allRows = paginationData.flatMap((item) =>
    'rows' in item ? item.rows : [item],
  )
  const pageRows = new Set(
    allRows
      .slice(pageIndex * pageSize, (pageIndex + 1) * pageSize)
      .map((row) => row.id),
  )
  // Count data rows, not headings, and preserve each item's position and group membership.
  const data = paginationData.flatMap(
    (item): DataTableData<PaginatedRepository> => {
      if ('rows' in item) {
        const rows = item.rows.filter((row) => pageRows.has(row.id))
        return rows.length > 0
          ? [
              {
                ...item,
                rows,
              },
            ]
          : []
      }
      return pageRows.has(item.id) ? [item] : []
    },
  )
  return (
    <Table.Container>
      <Table.Title as="h2" id={titleId}>
        Paginated repositories by visibility
      </Table.Title>
      <DataTable
        aria-labelledby={titleId}
        data={data}
        columns={[
          {
            header: 'Name',
            field: 'name',
            rowHeader: true,
            sortBy: true,
          },
          {
            header: 'Visibility',
            field: 'visibility',
          },
        ]}
      />
      <Table.Pagination
        aria-label="Pagination for grouped repositories"
        pageSize={pageSize}
        totalCount={allRows.length}
        onChange={({ pageIndex }) => setPageIndex(pageIndex)}
      />
    </Table.Container>
  )
}

